      OR (before_run->>'observedAt')::timestamptz<(q->>'dispatchAt')::timestamptz OR (before_run->>'observedAt')::timestamptz>(b->>'stopAttemptAt')::timestamptz
      OR (before_run->>'observedAt')::timestamptz>=(deletion->>'occurredAt')::timestamptz
      OR (deletion->>'occurredAt')::timestamptz<(b->>'stopAttemptAt')::timestamptz OR (deletion->>'occurredAt')::timestamptz>(first_zero->>'observedAt')::timestamptz
      OR regexp_replace(deletion->>'rawTimestamp','([.][0-9]{3})[0-9]+',E'\\1')::timestamptz IS DISTINCT FROM (deletion->>'occurredAt')::timestamptz
      OR deletion->'containerId' IS DISTINCT FROM x->'identity'->'containerId' OR deletion->'daemonId' IS DISTINCT FROM p->'executor'->'daemonId'
      OR deletion->'daemonBootId' IS DISTINCT FROM p->'executor'->'daemonBootId' THEN RETURN false; END IF;
    FOREACH t IN ARRAY ARRAY[before_run->>'observedAt',deletion->>'occurredAt'] LOOP
      IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t THEN RETURN false; END IF;
    END LOOP;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
