-- Reuse the immutable0134 snapshot of the COMPLETE pre0134 binding checks.
CREATE FUNCTION nmv_cli_executor_removed_request_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE e jsonb:=v->'terminal_evidence'; q jsonb:=e->'plan'->'request'; b jsonb:=v->'dispatch_binding';
BEGIN
  RETURN coalesce(v->>'state'='withdrawn' AND v->'settled_at'='null'::jsonb AND v->'token'<>'null'::jsonb
    AND nmv_cli_executor_removed_release_valid(e) AND nmv_cli_executor_predecessor_valid(v)
    AND v->>'terminal_evidence_hash'=encode(sha256(convert_to(nmv_boundary_canonical(e),'UTF8')),'hex')
    AND e->>'requestId'=v->>'request_id' AND e->'owner'->>'instanceId'=v->>'owner_instance_id' AND e->'owner'->>'bootId'=v->>'owner_boot_id'
    AND e->>'bindingHash'=v->>'dispatch_binding_hash' AND (e->>'dispatchAt')::timestamptz=(v->>'dispatched_at')::timestamptz
    AND q->>'tokenHash'=encode(sha256(convert_to(v->>'token','UTF8')),'hex') AND q->'epoch'=v->'epoch' AND q->'revision'=v->'revision'
    AND q->>'policyHash'=v->>'policy_hash' AND q->>'providerBudgetId'=v->>'provider_budget_id' AND q->>'groupId'=v->>'group_id'
    AND q->>'routeId'=v->>'route_id' AND q->>'provider'=v->>'provider' AND q->>'model'=v->>'model' AND q->>'logicalWorkKey'=v->>'logical_work_key'
    AND b->>'kind'='publication_classify_cli' AND v->>'dispatch_binding_hash'=encode(sha256(convert_to(nmv_boundary_canonical(b),'UTF8')),'hex')
    AND q->'inputHash'=b->'inputHash' AND q->'payloadHash'=b->'payloadHash'
    AND q->'transport'=b->'transport' AND q->'totalTokenBound'=b->'totalTokenBound' AND q->'chargedTokens'=b->'chargedTokens',false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
--> statement-breakpoint
CREATE FUNCTION nmv_cli_executor_removed_event_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE e jsonb:=v->'evidence';
BEGIN
  RETURN coalesce(v->>'kind'='dispatch_released' AND v->>'from_state'='dispatched' AND v->>'to_state'='withdrawn' AND v->'reason'='null'::jsonb
    AND nmv_cli_executor_removed_release_valid(e) AND e->>'requestId'=v->>'request_id'
    AND e->'plan'->'request'->'epoch'=v->'epoch' AND e->'plan'->'request'->'revision'=v->'revision'
    AND e->'plan'->'request'->'policyHash'=v->'policy_hash',false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
--> statement-breakpoint
DO $$
DECLARE n text; old_predicate text;
BEGIN
  FOREACH n IN ARRAY ARRAY['model_capacity_requests_logical_check','model_capacity_requests_members_check','model_capacity_requests_dispatch_check','model_capacity_requests_terminal_check'] LOOP
    SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate FROM pg_constraint WHERE conrelid='model_capacity_requests'::regclass AND conname=n;
    EXECUTE format('ALTER TABLE model_capacity_requests DROP CONSTRAINT %I',n);
    EXECUTE format('ALTER TABLE model_capacity_requests ADD CONSTRAINT %I CHECK ((%s) OR nmv_cli_executor_removed_request_valid(to_jsonb(model_capacity_requests)))',n,old_predicate);
  END LOOP;
  SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate FROM pg_constraint WHERE conrelid='model_capacity_events'::regclass AND conname='model_capacity_events_kind_check';
  ALTER TABLE model_capacity_events DROP CONSTRAINT model_capacity_events_kind_check;
  EXECUTE 'ALTER TABLE model_capacity_events ADD CONSTRAINT model_capacity_events_kind_check CHECK (('||old_predicate||') OR nmv_cli_executor_removed_event_valid(to_jsonb(model_capacity_events)))';
END $$;
--> statement-breakpoint
CREATE FUNCTION nmv_cli_executor_removed_transition_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c model_capacity_control; f dr_writer_fence; observed_now timestamptz;
BEGIN
  IF TG_OP='UPDATE' AND OLD.terminal_evidence->>'kind'='cli_executor_removed_boundary_exit' THEN
    IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'cli_executor_terminal_immutable';
  END IF;
  IF NEW.terminal_evidence->>'kind' IS DISTINCT FROM 'cli_executor_removed_boundary_exit' THEN RETURN NEW; END IF;
  IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'cli_executor_transition_invalid'; END IF;
  SELECT * INTO STRICT f FROM dr_writer_fence WHERE id=1 FOR SHARE;
  SELECT * INTO STRICT c FROM model_capacity_control WHERE id=1 FOR UPDATE;
  observed_now:=clock_timestamp();
  IF f.state<>'active' OR c.mode<>'draining' OR OLD.state<>'dispatched' OR NEW.state<>'withdrawn' OR OLD.terminal_evidence IS NOT NULL OR OLD.settled_at IS NOT NULL
    OR (to_jsonb(OLD)-ARRAY['state','terminal_evidence','terminal_evidence_hash','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','terminal_evidence','terminal_evidence_hash','updated_at'])
    OR NEW.terminal_evidence->'plan'->'writer' IS DISTINCT FROM jsonb_build_object('lineageId',f.lineage_id,'writerEpoch',f.writer_epoch)
    OR NEW.terminal_evidence->'plan'->'control' IS DISTINCT FROM jsonb_build_object('mode',c.mode,'epoch',c.epoch,'revision',c.revision,'policyHash',c.policy_hash,'updatedAt',to_char(c.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
    OR (NEW.terminal_evidence->>'evaluatedAt')::timestamptz NOT BETWEEN observed_now-interval '30 seconds' AND observed_now
    OR (NEW.terminal_evidence->'receipt'->>'observedAt')::timestamptz NOT BETWEEN observed_now-interval '5 minutes' AND observed_now
    OR (NEW.terminal_evidence->'receipt'->'removalBoundary'->'observations'->0->>'observedAt')::timestamptz NOT BETWEEN observed_now-interval '5 minutes' AND observed_now
    OR (NEW.terminal_evidence->'plan'->>'createdAt')::timestamptz NOT BETWEEN observed_now-interval '30 minutes' AND observed_now
    THEN RAISE EXCEPTION 'cli_executor_transition_conflict'; END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER model_capacity_cli_executor_removed_guard BEFORE INSERT OR UPDATE ON model_capacity_requests FOR EACH ROW EXECUTE FUNCTION nmv_cli_executor_removed_transition_guard();
